1	/**
2	 * ULID generation and validation. Every branded id in the app is produced
3	 * here, so ids sort lexicographically by creation time and the repositories
4	 * can use them as pagination cursors without a separate sort column.
5	 */
6	/** Crockford base32, minus I, L, O and U. */
7	const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
8	const TIME_LENGTH = 10;
9	const RANDOM_LENGTH = 16;
10	
11	const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;
12	
13	function encodeTime(time: number): string {
14	  let remaining = time;
15	  let out = "";
16	  for (let i = 0; i < TIME_LENGTH; i += 1) {
17	    const mod = remaining % 32;
