/**
 * Copies every live issue of `fromProjectId` into `toProjectId` for
 * `ProjectService.cloneProject`: title, description, priority, estimate,
 * labels and due date come along, renumbered from 1 in source-number order.
 * Status, assignee, parent and timestamps are reset — a clone is a fresh
 * start, not a mirror. Comments and attachments are never copied.
 */
export async function cloneIssuesToProject(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
  authorId: UserId,
  defaultStatus: IssueStatus,
): Promise<number> {
  const db = getDb();

  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, fromProjectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number)
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  const stamp = toIsoTimestamp(new Date());

  rows.forEach((row, index) => {
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: index + 1,
        title: row.title,
        description: row.description,
        status: defaultStatus,
        priority: row.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: row.estimate,
        dueAt: row.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    const labelIds = (labels[row.id] ?? []).map((label) => label.id);
    if (labelIds.length > 0) {
      db.insert(issueLabels)
        .values(labelIds.map((labelId) => ({ orgId, issueId: id, labelId })))
        .run();
    }
  });

  return rows.length;
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

