import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const projects = sqliteTable(
  "projects",
  {
    id: idColumn(),
    ...tenantColumns,
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    key: text("key").notNull(),
    description: text("description"),
    visibility: text("visibility", { enum: ["private", "org", "public"] })
      .notNull()
      .default("org"),
    status: text("status", { enum: ["active", "paused", "completed"] })
      .notNull()
      .default("active"),
    leadId: text("lead_id"),
    color: text("color").notNull().default("#6366f1"),
    startsAt: text("starts_at"),
    targetDate: text("target_date"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("projects_org_slug_idx").on(table.orgId, table.slug),
    uniqueIndex("projects_org_key_idx").on(table.orgId, table.key),
    index("projects_org_archived_idx").on(table.orgId, table.archivedAt),
  ],
);

export const projectMembers = sqliteTable(
  "project_members",
  {
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    userId: text("user_id").notNull(),
    addedAt: text("added_at").notNull(),
  },
  (table) => [
    uniqueIndex("project_members_pk").on(table.projectId, table.userId),
    index("project_members_org_idx").on(table.orgId),
  ],
);

export type ProjectRow = typeof projects.$inferSelect;
export type NewProjectRow = typeof projects.$inferInsert;
export type ProjectMemberRow = typeof projectMembers.$inferSelect;

/**
 * Copies a project's issues into another project, row for row, for the ops
 * console's "duplicate project" action: status, assignee and number come
 * along so the duplicate's board matches the original. Labels are copied too.
 */
export async function copyIssuesToProject(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const page = await listIssues({
    orgId,
    projectId: fromProjectId,
    limit: 100,
    cursor: null,
  });

  const stamp = toIsoTimestamp(new Date());
  for (const issue of page.items) {
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: issue.number,
        title: issue.title,
        description: issue.description,
        status: issue.status,
        priority: issue.priority,
        authorId: issue.authorId,
        assigneeId: issue.assigneeId,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        startedAt: issue.startedAt,
        completedAt: issue.completedAt,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    if (issue.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          issue.labelIds.map((labelId) => ({ orgId, issueId: id, labelId })),
        )
        .run();
    }
  }

  return page.items.length;
}

/**
 * Copies every live issue of `fromProjectId` into `toProjectId` for
 * `ProjectService.cloneProject`: title, description, priority, estimate,
 * labels and due date come along, renumbered from 1 in source-number order.
 * Status, assignee, parent and timestamps are reset — a clone is a fresh
 * start, not a mirror. Comments and attachments are never copied.
